import{_ as o,o as r,c as s,a3 as a}from"./chunks/framework.Cc-oPviL.js";const u=JSON.parse('{"title":"第六章　参数估计","description":"","frontmatter":{},"headers":[],"relativePath":"timeseries/06.md","filePath":"timeseries/06.md"}'),n={name:"timeseries/06.md"};function l(e,t,i,g,d,p){return r(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="第六章-参数估计" tabindex="-1">第六章　参数估计 <a class="header-anchor" href="#第六章-参数估计" aria-label="Permalink to &quot;第六章　参数估计&quot;">​</a></h1><p>结构定下来之后，剩下的是估参数、看显著性、判断参数是否可识别。本章覆盖矩估计、条件最小二乘与极大似然三条路线，并解释常数项为什么常常不显著。</p><h2 id="_6-1-矩估计" tabindex="-1">6.1 矩估计 <a class="header-anchor" href="#_6-1-矩估计" aria-label="Permalink to &quot;6.1 矩估计&quot;">​</a></h2><p>用样本自相关 ρ̂ₖ 代替理论值，代入 Yule-Walker 方程解出 φ：</p><blockquote><p><strong>P̂</strong> φ̂ = ρ̂</p></blockquote><p><strong>优点</strong>：有闭式解，计算快；解出的 φ 一定落在平稳域内（因为用的是非负定的样本自协方差矩阵）。</p><p><strong>缺点</strong>：效率低于极大似然；对 MA 部分不适用（MA 的 Yule-Walker 方程是二次的，解不唯一）；小样本偏差较大。</p><h2 id="_6-2-条件最小二乘-css" tabindex="-1">6.2 条件最小二乘（CSS） <a class="header-anchor" href="#_6-2-条件最小二乘-css" aria-label="Permalink to &quot;6.2 条件最小二乘（CSS）&quot;">​</a></h2><p>给定初始值（通常取 ε₁ = … = ε_p = 0 或取无条件均值），递推算出全部 εₜ，然后最小化</p><blockquote><p>Σₜ εₜ²</p></blockquote><p>这等价于<strong>条件似然</strong>（把前 p 个观测当作给定）。</p><p><strong>优点</strong>：计算简单，无需矩阵求逆；对 AR 部分等价于 OLS。</p><p><strong>缺点</strong>：结果依赖初始值的处理方式；对 MA 部分，条件似然与精确似然的差异在小样本下不可忽略；不可逆的 MA 会导致递推发散。</p><h2 id="_6-3-极大似然-mle" tabindex="-1">6.3 极大似然（MLE） <a class="header-anchor" href="#_6-3-极大似然-mle" aria-label="Permalink to &quot;6.3 极大似然（MLE）&quot;">​</a></h2><p>在正态假设下，精确对数似然为</p><blockquote><p>ln L = −(n/2) ln(2π) − (n/2) ln σ² − (1/2) ln|<strong>Ω</strong>| − (1/2σ²) <strong>y</strong>′<strong>Ω</strong>⁻¹<strong>y</strong></p></blockquote><p>其中 <strong>Ω</strong> 是自相关矩阵。实际计算用 <strong>Kalman 滤波</strong>递推，避免直接求 n×n 矩阵的逆。</p><p><strong>CSS-ML</strong>：先用 CSS 得到初值，再切换到精确 ML 优化。这是 R 的 <code>arima()</code> 的默认做法，兼顾稳健与效率。</p><p><strong>渐近性质</strong>：在正则条件下，MLE 是<strong>一致</strong>的、<strong>渐近正态</strong>的、<strong>渐近有效</strong>的（达到 Cramér-Rao 下界）。</p><h2 id="_6-4-标准误与显著性" tabindex="-1">6.4 标准误与显著性 <a class="header-anchor" href="#_6-4-标准误与显著性" aria-label="Permalink to &quot;6.4 标准误与显著性&quot;">​</a></h2><p>参数的渐近协方差矩阵为</p><blockquote><p>Var(φ̂) ≈ σ̂² (<strong>X</strong>′<strong>X</strong>)⁻¹</p></blockquote><p>其中 <strong>X</strong> 是滞后项构成的回归矩阵。于是</p><blockquote><p>z = 系数估计 / 标准误　~　N(0, 1)（渐近）</p></blockquote><p>★ <strong>为什么 ARIMA 报 z 值而不是 t 值？</strong> 因为 ARIMA 的推断是<strong>渐近</strong>的，依赖大样本正态近似，而不是像线性回归那样在正态误差下精确服从 t 分布。样本量足够时两者几乎一样；小样本时 z 值会略微高估显著性。</p><p><strong>95% 置信区间</strong>：估计值 ± 1.96 × 标准误。若区间跨过零，则该参数不显著。</p><h2 id="_6-5-为什么常数项-漂移项常常不显著" tabindex="-1">6.5 为什么常数项/漂移项常常不显著 <a class="header-anchor" href="#_6-5-为什么常数项-漂移项常常不显著" aria-label="Permalink to &quot;6.5 为什么常数项/漂移项常常不显著&quot;">​</a></h2><p>这是实践中极常见的现象，原因有四：</p><ol><li><strong>标准误被放大</strong>。常数项的估计涉及 (1 − Σφᵢ) 这个分母，当 Σφᵢ 接近 1 时，分母很小，标准误很大。</li><li><strong>差分后的常数项含义变了</strong>。在原序列里它是&quot;水平&quot;，在差分序列里它变成&quot;每期平均增量&quot;，量级通常很小。</li><li><strong>样本内水平变化大</strong>。若序列在样本期内经历大幅涨跌，长期均值的估计本身就不确定，标准误自然大。</li><li><strong>真实效应确实接近零</strong>。很多经济序列在样本期内没有稳定的长期漂移。</li></ol><p>★ <strong>不显著 ≠ 应该删除。</strong> 是否保留取决于：</p><ul><li>选模规则是否事先规定（若规则说&quot;按验证误差选&quot;，就不能因为不显著而删）；</li><li>预测目标（若关心长期预测，漂移项会被 h 放大，影响不可忽略）；</li><li>理论依据（若理论上应有趋势，不显著可能只是样本不足）。</li></ul><h2 id="_6-6-参数冗余与不可识别" tabindex="-1">6.6 参数冗余与不可识别 <a class="header-anchor" href="#_6-6-参数冗余与不可识别" aria-label="Permalink to &quot;6.6 参数冗余与不可识别&quot;">​</a></h2><p><strong>冗余</strong>的典型表现：</p><ul><li>AR 与 MA 部分的系数近似抵消（如 φ ≈ −θ）；</li><li>系数估计值很大但标准误更大，z 值接近零；</li><li>参数之间高度负相关；</li><li>不同初值收敛到差异很大的解。</li></ul><p><strong>原因</strong>：ARMA(p, q) 与 ARMA(p−1, q−1) 可能表示同一个过程。当公因子近似可约时，参数就无法唯一确定。</p><p><strong>处理</strong>：降阶；或固定某个参数为 0；或改用更简约的设定。</p><h2 id="_6-7-估计失败的常见原因" tabindex="-1">6.7 估计失败的常见原因 <a class="header-anchor" href="#_6-7-估计失败的常见原因" aria-label="Permalink to &quot;6.7 估计失败的常见原因&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>处理</th></tr></thead><tbody><tr><td>优化器不收敛</td><td>初值差、参数不可识别、模型过复杂</td><td>换初值、降阶、改用 CSS 给初值</td></tr><tr><td>根接近单位圆</td><td>过度差分、参数冗余</td><td>检查 d、降阶</td></tr><tr><td>标准误极大</td><td>参数不可识别、样本共线</td><td>降阶、检查数据</td></tr><tr><td>系数在边界上</td><td>真实参数接近 0 或 ±1</td><td>考虑简化模型</td></tr><tr><td>不同软件结果差异大</td><td>似然定义不同（条件/精确）、初值不同</td><td>统一设定、报告所用方法</td></tr></tbody></table><p>★ <strong>数据尺度会影响数值稳定性，但不影响结论。</strong> 用原始单位（如美元/桶）与用标准化后的数据估计，参数的 t 值、AIC 的可比性都不变（AIC 会差一个常数），但优化器的收敛行为可能不同。若遇收敛困难，可以先把数据缩放到单位方差再估计，最后把参数换算回原尺度。</p><h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2><ol><li>矩估计有闭式解且必落平稳域，但效率低；MLE 渐近有效，是默认选择。</li><li>CSS-ML = 先条件最小二乘给初值，再精确极大似然优化。</li><li>参数显著性用 z 值（渐近正态），95% 区间为估计 ± 1.96×SE。</li><li>常数/漂移项不显著很常见，原因是标准误被 (1−Σφ) 放大，不显著不等于应删。</li><li>系数大幅抵消、标准误极大是参数冗余的信号，应降阶。</li></ol><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：矩估计、CSS、MLE 各有什么特点？默认用哪个？</strong></p><details class="details custom-block"><summary>点开看答案</summary><ul><li><strong>矩估计</strong>：有闭式解，结果必落平稳域，但效率低；</li><li><strong>CSS（条件最小二乘）</strong>：常用来给初值；</li><li><strong>MLE（极大似然）</strong>：渐近有效，是<strong>默认选择</strong>。</li></ul><p>常见做法 <strong>CSS-ML</strong>：先用 CSS 给初值，再做精确极大似然优化。</p></details><p><strong>Q2：常数项/漂移项不显著，是不是就该删掉？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p><strong>不一定</strong>。它常常不显著，是因为标准误被 <strong>(1 − Σφ)</strong> 放大了；<strong>不显著不等于应删</strong>。</p><p>参数显著性用 z 值（渐近正态），95% 区间为估计 ± 1.96×SE。</p></details><p><strong>Q3：参数冗余有什么信号？该怎么处理？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>信号：<strong>系数大幅互相抵消、标准误极大</strong>（例如 AR 根和 MA 根几乎相等）。</p><p>处理：<strong>降阶</strong>。</p></details>',48)])])}const c=o(n,[["render",l]]);export{u as __pageData,c as default};
